/*
 This node takes the incoming Gmail item and creates one item per attachment.
 Each new item keeps the original email metadata in json and places the single attachment under its original binary key.
*/

const item = items[0];
const bin = item.binary || {};
const binKeys = Object.keys(bin);
const out = [];
if (binKeys.length === 0) {
  // No binary attachments; try to use attachments metadata if present (rare)
  return [];
}

for (let i = 0; i < binKeys.length; i++) {
  const key = binKeys[i];
  const newItem = {
    json: Object.assign({}, item.json, { originalFileName: key, attachmentIndex: i }),
    binary: {
      // keep the original key for now; Move Binary Data will standardize to 'data'
      [key]: bin[key]
    }
  };
  out.push(newItem);
}

return out;

/*
 Prepares a deterministic prompt for the OpenAI node and extracts sender metadata.
*/
const item = items[0];
const j = item.json || {};
const binKeys = Object.keys(item.binary || {});
const originalFileName = j.originalFileName || binKeys[0] || 'attachment.bin';

// try to extract sender name and email
let from = j.from || j.fromValue || '';
let senderName = '';
let senderEmail = '';
if (from) {
  const m = from.match(/(.*)\s+<([^>]+)>/);
  if (m) {
    senderName = m[1].replace(/\"/g, '').trim();
    senderEmail = m[2].trim();
  } else {
    // sometimes it's just the email
    senderEmail = from.trim();
  }
}
if (!senderEmail && j.headers && j.headers.From) {
  senderEmail = j.headers.From;
}
const senderDomain = (senderEmail && senderEmail.split('@')[1]) || (senderName && senderName.split(' ').slice(-1)[0]) || 'fournisseur-inconnu';
const dateRaw = j.date || new Date().toISOString();
const dateIso = (new Date(dateRaw)).toISOString().split('T')[0];

// build a strict prompt asking for JSON only to ease parsing
const prompt = `You are a filename-normalization assistant for accounting. Respond ONLY with a single JSON object, no explanation, no surrounding markdown.\nInput: original filename: "${originalFileName}"\nEmail subject: "${(j.subject||'').replace(/\"/g,'') }"\nSender name: "${senderName}"\nSender domain: "${senderDomain}"\nDate: ${dateIso}\nRules: produce keys: normalized_file_name (string) and category (one of: facture, devis, contrat, autre). The normalized_file_name must keep the original extension and start with the date in YYYY-MM-DD format, e.g. 2026-09-14_Facture_Fournisseur-Martin.pdf.`;

item.json.prompt = prompt;
item.json.originalFileName = originalFileName;
item.json.senderDomain = senderDomain;
item.json.senderName = senderName;
item.json.date = dateIso;

return items;

/*
 This node parses the AI response which is expected to be pure JSON. If parsing fails or fields missing, we build a safe fallback filename and category.
*/
const item = items[0];
let aiText = '';
if (item.json && item.json.text) aiText = item.json.text; // older node outputs
if (!aiText && item.json && item.json.choices && item.json.choices[0]) {
  const c = item.json.choices[0];
  aiText = (c.message && c.message.content) || c.text || '';
}
if (!aiText && item.json && item.json.output) aiText = item.json.output;
if (!aiText && item.json && item.json.message && item.json.message.content) aiText = item.json.message.content;

let parsed = null;
try {
  parsed = JSON.parse(aiText.trim());
} catch (e) {
  parsed = null;
}

const orig = item.json.originalFileName || 'attachment.bin';
const ext = orig.includes('.') ? orig.substring(orig.lastIndexOf('.')) : '';
let normalized = null;
let category = null;
if (parsed && typeof parsed === 'object') {
  normalized = parsed.normalized_file_name || parsed.normalizedFileName || parsed.filename || null;
  category = parsed.category || parsed.type || null;
}
// fallback if AI failed or returned invalid data
if (!category) category = 'autre';
if (!normalized) {
  // sanitize original filename
  const safeBase = orig.replace(/\.[^.]+$/, '').replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_\-]/g, '_');
  normalized = `${item.json.date || (new Date()).toISOString().split('T')[0]}_${category}_${(item.json.senderDomain||'fournisseur')}_${safeBase}${ext}`;
}
// final safety: ensure extension present
if (!normalized.includes('.') && ext) normalized = `${normalized}${ext}`;

item.json.normalizedFileName = normalized;
item.json.category = category;

return items;
